package com.cpf.starter.ftps;import java.io.*;import java.nio.file.*;import java.util.*;import org.apache.commons.net.ftp.*;public final class CpfFtpsClient {private final CpfFtpsProperties p;public CpfFtpsClient(CpfFtpsProperties p){this.p=p;}public void upload(Path local,String remote)throws IOException{if(Files.size(local)>p.getMaxBytes())throw new IOException("FTPS limit");with(c->{try(InputStream in=Files.newInputStream(local)){if(!c.storeFile(remote,in))throw new IOException("FTPS upload rejected: "+c.getReplyString());}return null;});}public void download(String remote,Path local)throws IOException{Files.createDirectories(local.toAbsolutePath().getParent());with(c->{try(InputStream in=c.retrieveFileStream(remote);OutputStream out=Files.newOutputStream(local)){if(in==null)throw new IOException("FTPS missing remote");in.transferTo(new Limited(out,p.getMaxBytes()));}if(!c.completePendingCommand())throw new IOException("FTPS completion failed");return null;});}public List<String> list(String dir)throws IOException{return with(c->Arrays.stream(c.listFiles(dir)).map(FTPFile::getName).toList());}public void move(String a,String b)throws IOException{with(c->{if(!c.rename(a,b))throw new IOException("FTPS rename failed");return null;});}public void delete(String path)throws IOException{with(c->{if(!c.deleteFile(path))throw new IOException("FTPS delete failed");return null;});}private <T>T with(Operation<T> op)throws IOException{p.validate();FTPSClient c=new FTPSClient(p.isImplicit());try{c.setConnectTimeout((int)p.getTimeout().toMillis());c.connect(p.getHost(),p.getPort());if(!c.login(p.getUsername(),p.getPassword()))throw new IOException("FTPS auth failed");c.execPBSZ(0);c.execPROT("P");c.enterLocalPassiveMode();c.setFileType(FTP.BINARY_FILE_TYPE);return op.apply(c);}finally{if(c.isConnected())try{c.logout();c.disconnect();}catch(IOException ignored){}}}private interface Operation<T>{T apply(FTPSClient c)throws IOException;}private static final class Limited extends FilterOutputStream{long n,max;Limited(OutputStream o,long m){super(o);max=m;}public void write(byte[] b,int o,int l)throws IOException{n+=l;if(n>max)throw new IOException("FTPS limit");super.write(b,o,l);}public void write(int b)throws IOException{if(++n>max)throw new IOException("FTPS limit");super.write(b);}}}
